'use strict';
const $=id=>document.getElementById(id);
const NS='http://www.w3.org/2000/svg';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=value=>JSON.parse(JSON.stringify(value));
const statusNames={unmarked:'未标注',marked:'已标注',review:'待确认',unknown:'无法定位'};
const S={maps:null,photos:[],filtered:[],selected:new Set(),current:null,annotation:null,entities:[],floor:'GF',mapMode:'camera',mapZoom:1,mapCenter:null,photoZoom:1,photoCenter:null,boxMode:false,dirty:false,generation:0,saving:null,saveTimer:null,view:'annotate',measure:[],polygon:[],jobs:[],config:{},hoverRegion:null};
async function api(path,value){const r=await fetch(path,value===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data;}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function on(id,event,fn){$(id).addEventListener(event,e=>Promise.resolve().then(()=>fn(e)).catch(error=>toast(error.message)));}
function svgEl(name,attrs={},text){const el=document.createElementNS(NS,name);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;return el;}
function floorData(id=S.floor){return S.maps.floors.find(f=>f.id===id);}
function cal(id=S.floor){return S.maps.calibration.floors[id];}
function meters(x,y,id=S.floor){const c=cal(id);return[c.x.scale*x+c.x.offset,c.y.scale*y+c.y.offset];}
function pixels(x,y,id=S.floor){const c=cal(id);return[(x-c.x.offset)/c.x.scale,(y-c.y.offset)/c.y.scale];}
function polygonPath(points){return'M'+points.map(p=>p.join(',')).join('L')+'Z';}
function bounds(points){const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);return[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)];}
function inPolygon([x,y],polygon){let result=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const[x1,y1]=polygon[j],[x2,y2]=polygon[i];if((y1>y)!==(y2>y)&&x<(x2-x1)*(y-y1)/(y2-y1)+x1)result=!result;}return result;}
function regionsAt(x,y,id=S.floor){return floorData(id).regions.filter(r=>inPolygon([x,y],r.points));}
function regionName(id,floor=S.floor){return floorData(floor)?.regions.find(r=>r.id===id)?.label||'';}
function regionOption(r){return `${r.id} · ${r.label}${r.is_historical_subregion?'（历史子区）':''}`;}
function svgPoint(svg,event){const point=new DOMPoint(event.clientX,event.clientY);return point.matrixTransform(svg.getScreenCTM().inverse());}
function setSaveState(text,kind=''){$('save-state').textContent=text;$('save-state').className='save-state '+kind;}
function touch(){if(!S.current)return;S.dirty=true;S.generation++;setSaveState('待保存','saving');clearTimeout(S.saveTimer);S.saveTimer=setTimeout(()=>flush().catch(e=>{setSaveState('保存失败','error');toast(e.message);}),650);}
async function flush(){clearTimeout(S.saveTimer);if(S.saving)await S.saving;if(!S.dirty||!S.current)return;const pid=S.current.id;while(S.dirty&&S.current?.id===pid){const generation=S.generation;const snapshot=clone(S.annotation);setSaveState('正在保存','saving');S.saving=api('/api/save',{photo_id:pid,annotation:snapshot,expected_revision:snapshot.revision});let saved;try{saved=await S.saving;}catch(e){setSaveState('保存失败','error');throw e;}finally{S.saving=null;}S.annotation.revision=saved.revision;S.annotation.updated_at=saved.updated_at;if(S.generation===generation){S.annotation=saved;S.dirty=false;}const p=S.photos.find(p=>p.id===pid);p.annotation=clone(saved);S.current.annotation=clone(saved);setSaveState('已保存到磁盘');updateProgress();updateCard(pid);if(S.dirty)continue;renderPositionValues();$('annotation-history').textContent=`修订 ${S.annotation.revision} · ${new Date(S.annotation.updated_at).toLocaleString()}`;}}
function updateCard(pid){const row=document.querySelector(`.photo-card[data-id="${pid}"]`);const photo=S.photos.find(p=>p.id===pid);if(row){const status=row.querySelector('.photo-status');status.className='photo-status '+photo.annotation.status;status.textContent=statusNames[photo.annotation.status];}}
function updateProgress(){const done=S.photos.filter(p=>p.annotation.status==='marked').length;const review=S.photos.filter(p=>p.annotation.status==='review').length;$('total-count').textContent=S.photos.length+' 张';$('progress-line').textContent=`已标注 ${done} · 待确认 ${review} · 未标注 ${S.photos.filter(p=>p.annotation.status==='unmarked').length}`;$('selected-count').textContent=S.selected.size;}
function buildFolders(){const counts=new Map();for(const p of S.photos){const f=p.folder_hint||'其他';const c=counts.get(f)||[0,0];c[0]++;if(p.annotation.status==='marked')c[1]++;counts.set(f,c);}const previous=$('folder-filter').value;$('folder-filter').replaceChildren(new Option('所有文件夹',''));for(const[name,c]of [...counts.entries()].sort((a,b)=>a[0].localeCompare(b[0])))$('folder-filter').append(new Option(`${name} · ${c[1]}/${c[0]}`,name));$('folder-filter').value=previous;}
function filterPhotos(){const folder=$('folder-filter').value,status=$('status-filter').value,floor=$('photo-floor-filter').value,q=$('photo-search').value.toLowerCase();S.filtered=S.photos.filter(p=>(!folder||p.folder_hint===folder)&&(!status||p.annotation.status===status)&&(!floor||(floor==='unknown'?!p.annotation.floor:p.annotation.floor===floor))&&(!q||(`${p.name} ${p.folder_hint} ${JSON.stringify(p.annotation.notes)}`).toLowerCase().includes(q)));renderLibrary();}
function renderLibrary(){const scroll=$('photo-list').scrollTop;$('photo-list').replaceChildren();for(const p of S.filtered){const row=document.createElement('div');row.className='photo-card'+(S.current?.id===p.id?' active':'');row.dataset.id=p.id;row.innerHTML=`<input type="checkbox" aria-label="勾选 ${esc(p.name)}" ${S.selected.has(p.id)?'checked':''}><img loading="lazy" src="/api/image/${p.id}?size=200" alt=""><div><div class="name">${esc(p.name)}</div><span class="photo-status ${esc(p.annotation.status)}">${statusNames[p.annotation.status]}</span></div>`;row.querySelector('input').addEventListener('click',e=>{e.stopPropagation();if(e.target.checked)S.selected.add(p.id);else S.selected.delete(p.id);updateProgress();});row.addEventListener('click',()=>selectPhoto(p.id).catch(e=>toast(e.message)));$('photo-list').append(row);}if(!S.filtered.length)$('photo-list').innerHTML='<div class="empty-list">当前筛选下没有照片。</div>';$('photo-list').scrollTop=scroll;updateProgress();updateNav();}
function updateNav(){const i=S.filtered.findIndex(p=>p.id===S.current?.id);$('photo-index').textContent=`${i<0?0:i+1} / ${S.filtered.length}`;$('previous-photo').disabled=i<=0;$('next-photo').disabled=i<0||i>=S.filtered.length-1;}
async function selectPhoto(id){if(S.loading)return;await flush();S.refreshSequence=(S.refreshSequence||0)+1;S.loading=true;document.body.classList.add('photo-loading');$('annotate-view').setAttribute('aria-busy','true');setSaveState('正在加载照片');let detail;try{detail=await api('/api/photo/'+id);}catch(error){S.loading=false;document.body.classList.remove('photo-loading');$('annotate-view').setAttribute('aria-busy','false');throw error;}S.current=detail;S.annotation=clone(detail.annotation);S.dirty=false;S.generation=0;S.photoZoom=1;S.photoCenter=[detail.width/2,detail.height/2];S.boxMode=false;S.polygon=[];S.measure=[];S.floor=S.annotation.floor||inferFloor(detail)||S.floor;$('photo-name').textContent=detail.name;$('photo-meta').textContent=`${detail.width} × ${detail.height} · ${(detail.bytes/1048576).toFixed(1)} MB`;$('candidate-photo').textContent=detail.name;$('photo-empty').hidden=true;const img=$('photo-image');img.setAttribute('href',`/api/image/${id}?size=original`);img.setAttribute('width',detail.width);img.setAttribute('height',detail.height);$('photo-zoom').value=1;renderPhoto();renderMap();fillForm();renderRelations();renderCandidates();renderFacts();renderLibrary();const source=detail.sources?.[0]||detail;const sourceUrl=source.page||source.src;$('source-label').innerHTML=`${esc(detail.folder_hint)} · ${source.source_type==='website'?'官方网站照片':'现场照片'}${sourceUrl?` · <a href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">查看来源</a>`:''}`;S.loading=false;document.body.classList.remove('photo-loading');$('annotate-view').setAttribute('aria-busy','false');setSaveState('已载入 · 自动保存');localStorage.setItem('innowing-last-photo',id);}
function inferFloor(photo){const name=photo.folder_hint.toLowerCase();return name.includes('makerspace')||name.includes('进门')?'GF':name.includes('brainstorm')||name.includes('digital')||name.includes('event')||name.includes('posters')?'LGF':null;}
async function movePhoto(delta){const i=S.filtered.findIndex(p=>p.id===S.current?.id);if(i+delta>=0&&i+delta<S.filtered.length)await selectPhoto(S.filtered[i+delta].id);}
function renderPhoto(){if(!S.current)return;const w=S.current.width/S.photoZoom,h=S.current.height/S.photoZoom;S.photoCenter[0]=Math.max(w/2,Math.min(S.current.width-w/2,S.photoCenter[0]));S.photoCenter[1]=Math.max(h/2,Math.min(S.current.height-h/2,S.photoCenter[1]));$('photo-svg').setAttribute('viewBox',`${S.photoCenter[0]-w/2} ${S.photoCenter[1]-h/2} ${w} ${h}`);$('photo-zoom-label').textContent=S.photoZoom+'×';$('photo-zoom').value=S.photoZoom;$('box-mode').classList.toggle('active',S.boxMode);$('photo-boxes').replaceChildren();for(const box of S.annotation.boxes||[]){const attrs={x:box.x*S.current.width,y:box.y*S.current.height,width:box.width*S.current.width,height:box.height*S.current.height,fill:'#f5b64520',stroke:'#f2ad2f','stroke-width':3,'vector-effect':'non-scaling-stroke'};$('photo-boxes').append(svgEl('rect',attrs));}$('box-list').replaceChildren();for(const box of S.annotation.boxes||[]){const chip=document.createElement('div');chip.className='box-chip';chip.innerHTML=`${esc(box.name||'细节框')}<button aria-label="删除框选">×</button>`;chip.querySelector('button').onclick=()=>{S.annotation.boxes=S.annotation.boxes.filter(b=>b.id!==box.id);touch();renderPhoto();};$('box-list').append(chip);}}
function fillRegionSelect(select,floor,empty='未确定'){const value=select.value;select.replaceChildren(new Option(empty,''));for(const r of floorData(floor).regions)select.append(new Option(regionOption(r),r.id));select.value=value;}
function renderMap(){const floor=floorData();const image=$('map-image');image.setAttribute('href','/assets/'+floor.image);image.setAttribute('width',floor.width);image.setAttribute('height',floor.height);image.style.display=$('map-background').value==='regions'?'none':'';$('map-floor').value=S.floor;S.mapCenter=[floor.width/2,floor.height/2];S.mapZoom=1;$('map-zoom').value=1;$('map-regions').replaceChildren();for(const r of floor.regions){const path=svgEl('path',{d:polygonPath(r.points),class:`region-shape ${r.type} ${r.is_historical_subregion?'historical':''}`,'data-region-id':r.id});path.append(svgEl('title',{},`${r.label}${r.official_plan_name&&r.official_plan_name!==r.label?' · 尺寸图：'+r.official_plan_name:''}`));path.addEventListener('mouseenter',()=>{S.hoverRegion=r.id;$('map-detail').textContent=`${r.id} · ${r.label}${r.official_plan_name&&r.official_plan_name!==r.label?' · 尺寸图原名：'+r.official_plan_name:''}${r.is_historical_subregion?' · 合并空间的历史子区':''}`;});$('map-regions').append(path);}$('map-regions').style.display=$('map-background').value==='original'?'none':'';fillRegionSelect($('camera-area'),S.floor);setMapView();renderMarks();}
function setMapView(){const floor=floorData(),w=floor.width/S.mapZoom,h=floor.height/S.mapZoom;S.mapCenter[0]=Math.max(w/2,Math.min(floor.width-w/2,S.mapCenter[0]));S.mapCenter[1]=Math.max(h/2,Math.min(floor.height-h/2,S.mapCenter[1]));$('map-svg').setAttribute('viewBox',`${S.mapCenter[0]-w/2} ${S.mapCenter[1]-h/2} ${w} ${h}`);renderMapLabels();renderGrid();renderMarks();}
function screenScale(){const svg=$('map-svg'),matrix=svg.getScreenCTM();return matrix?Math.hypot(matrix.a,matrix.b):1;}
function renderMapLabels(){const group=$('map-names');group.replaceChildren();if(!$('map-labels').checked||$('map-background').value==='original')return;const scale=screenScale()||1;for(const r of floorData().regions){const[x1,y1,x2,y2]=bounds(r.points),width=(x2-x1)*scale,height=(y2-y1)*scale;const font=11/scale;const maxChars=Math.max(5,Math.floor(width/6));const words=r.label.split(' ');let lines=[],line='';for(const word of words){if((line+' '+word).trim().length>maxChars&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);if(width<40||height<25)continue;if(lines.length>3)lines=[...lines.slice(0,2),lines.slice(2).join(' ')];if(lines[2]?.length>maxChars)lines[2]=lines[2].slice(0,maxChars-1)+'…';if(lines.length*12>height)lines=[r.short_label?.slice(0,maxChars)||r.label.slice(0,maxChars)];const text=svgEl('text',{x:r.at[0],y:r.at[1]-(lines.length-1)*font*.6,'text-anchor':'middle','font-size':font,class:'map-region-name'});lines.forEach((line,i)=>text.append(svgEl('tspan',{x:r.at[0],dy:i?font*1.2:0},line)));group.append(text);}}
function renderGrid(){const group=$('map-grid');group.replaceChildren();if(!$('map-grid-toggle').checked)return;const c=cal(),[x0,y0]=pixels(0,0),[xMax,yMax]=pixels(46.56,25.56),scale=screenScale()||1;for(let x=0;x<=45;x+=5){const[px]=pixels(x,0);group.append(svgEl('line',{x1:px,y1:y0,x2:px,y2:yMax,stroke:'#658fbd','stroke-opacity':'.18','stroke-width':1,'vector-effect':'non-scaling-stroke'}));group.append(svgEl('text',{x:px,y:y0+16/scale,'text-anchor':'middle','font-size':10/scale,fill:'#607d9c','paint-order':'stroke',stroke:'#fff','stroke-width':2},x+'m'));}for(let y=0;y<=25;y+=5){const[,py]=pixels(0,y);group.append(svgEl('line',{x1:x0,y1:py,x2:xMax,y2:py,stroke:'#658fbd','stroke-opacity':'.18','stroke-width':1,'vector-effect':'non-scaling-stroke'}));group.append(svgEl('text',{x:x0-4/scale,y:py,'text-anchor':'end','font-size':10/scale,fill:'#607d9c','paint-order':'stroke',stroke:'#fff','stroke-width':2},y+'m'));}}
function renderMarks(){const group=$('map-marks');group.replaceChildren();if(!S.annotation)return;const scale=screenScale()||1;const camera=S.annotation.camera;const sameFloor=S.annotation.floor===S.floor;for(const r of document.querySelectorAll('.region-shape'))r.classList.toggle('selected',r.dataset.regionId===S.annotation.camera_area&&sameFloor);
  const line=(a,b,color='#2563eb')=>group.append(svgEl('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:color,'stroke-width':2,'vector-effect':'non-scaling-stroke','marker-end':color==='#2563eb'?'url(#camera-arrow)':''}));
  const circle=(x,y,color,kind,id)=>{const e=svgEl('circle',{cx:x,cy:y,r:7/scale,fill:color,stroke:'#fff','stroke-width':2,'vector-effect':'non-scaling-stroke','data-mark-kind':kind,'data-mark-id':id||''});group.append(e);return e;};
  if(camera&&sameFloor){if(S.annotation.heading_deg!==null){const start=meters(camera.x_px,camera.y_px);const angle=S.annotation.heading_deg*Math.PI/180,end=pixels(start[0]+Math.sin(angle)*4,start[1]+Math.cos(angle)*4);if(S.annotation.fov_deg){const half=S.annotation.fov_deg*Math.PI/360;const wedge=[[camera.x_px,camera.y_px]];for(let i=0;i<=20;i++){const a=angle-half+2*half*i/20;wedge.push(pixels(start[0]+Math.sin(a)*6,start[1]+Math.cos(a)*6));}group.append(svgEl('path',{d:polygonPath(wedge),fill:'#3b82f620',stroke:'none'}));}line([camera.x_px,camera.y_px],end);circle(end[0],end[1],'#8cb5ff','heading');}circle(camera.x_px,camera.y_px,'#2563eb','camera');}
  for(const target of S.annotation.targets||[]){if((target.floor||S.annotation.floor)!==S.floor)continue;if(target.type==='area'&&target.points_px){group.append(svgEl('path',{d:polygonPath(target.points_px),fill:'#d99f3525',stroke:'#bf892c','stroke-width':2,'stroke-dasharray':'4 3','vector-effect':'non-scaling-stroke'}));}else{circle(target.x_px,target.y_px,'#d69626','target',target.id);group.append(svgEl('text',{x:target.x_px+10/scale,y:target.y_px-7/scale,'font-size':11/scale,fill:'#926722','paint-order':'stroke',stroke:'#fff','stroke-width':3},target.name));}}
  if(sameFloor)for(const coverage of S.annotation.coverage||[]){group.append(svgEl('path',{d:polygonPath(coverage.points_px),fill:'#27aa9220',stroke:'#238d79','stroke-width':2,'stroke-dasharray':'6 3','vector-effect':'non-scaling-stroke'}));}
  if(S.polygon.length){group.append(svgEl('polyline',{points:S.polygon.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#238d79','stroke-width':2,'vector-effect':'non-scaling-stroke'}));S.polygon.forEach(p=>circle(p[0],p[1],'#238d79','polygon'));}
  if(S.measure.length){S.measure.forEach(p=>circle(p[0],p[1],'#a65fc6','measure'));if(S.measure.length===2){line(S.measure[0],S.measure[1],'#a65fc6');const a=meters(...S.measure[0]),b=meters(...S.measure[1]);$('measure-result').textContent=`两点平面直线距离：${Math.hypot(a[0]-b[0],a[1]-b[1]).toFixed(2)} m · 图纸校准，单位待核验`;$('measure-result').hidden=false;}}
}
function setHeading(x,y){if(!S.annotation.camera){toast('先设置拍摄点。');return;}const c=S.annotation.camera,a=meters(c.x_px,c.y_px),b=meters(x,y);let angle=Math.atan2(b[0]-a[0],b[1]-a[1])*180/Math.PI;if(angle<0)angle+=360;S.annotation.heading_deg=Math.round(angle*10)/10;S.annotation.heading_confidence='estimated';if(S.annotation.status==='unmarked'||S.annotation.status==='review')S.annotation.status='marked';touch();renderPositionValues();renderMarks();}
function placeCamera(x,y){const hits=regionsAt(x,y);S.annotation.floor=S.floor;S.annotation.camera={x_px:x,y_px:y};const m=meters(x,y);S.annotation.camera.x_m=m[0];S.annotation.camera.y_m=m[1];S.annotation.camera_area=hits.find(r=>r.type!=='circulation')?.id||hits[0]?.id||null;S.annotation.position_confidence='estimated';S.annotation.status=S.annotation.heading_deg===null?'review':'marked';touch();fillForm();renderMarks();}
function placeTarget(x,y){const hits=regionsAt(x,y);const m=meters(x,y);S.annotation.floor||=S.floor;const target={id:'target_'+crypto.randomUUID().slice(0,12),type:'point',floor:S.floor,name:$('new-target-name').value.trim()||'未命名目标',entity_id:$('new-target-entity').value||null,x_px:x,y_px:y,x_m:m[0],y_m:m[1],area_id:hits.find(r=>r.type!=='circulation')?.id||hits[0]?.id||null,confidence:'estimated',note:''};S.annotation.targets.push(target);touch();renderTargets();renderMarks();}
function renderPositionValues(){const c=S.annotation?.camera;$('camera-x').value=c&&S.annotation.floor===S.floor?meters(c.x_px,c.y_px)[0].toFixed(2):'';$('camera-y').value=c&&S.annotation.floor===S.floor?meters(c.x_px,c.y_px)[1].toFixed(2):'';$('heading').value=S.annotation?.heading_deg??'';$('camera-area').value=S.annotation?.camera_area??'';$('position-confidence').value=S.annotation?.position_confidence||'unknown';$('heading-confidence').value=S.annotation?.heading_confidence||'unknown';$('annotation-status').value=S.annotation?.status||'unmarked';}
function fillForm(){if(!S.annotation)return;const a=S.annotation;renderPositionValues();$('fov').value=a.fov_deg??'';$('pitch').value=a.pitch_deg??'';$('pitch-mode').value=a.pitch_mode||'horizontal';$('captured-at').value=a.captured_at||'';$('photo-type').value=a.photo_type||'overview';$('group-id').value=a.group_id||'';$('tags').value=(a.tags||[]).join(', ');for(const[k,id]of Object.entries({shooting:'note-shooting',content:'note-content',correspondence:'note-correspondence',uncertainty:'note-uncertainty'}))$(id).value=a.notes?.[k]||'';$('annotation-history').textContent=`修订 ${a.revision} · ${a.updated_at?new Date(a.updated_at).toLocaleString():'尚未保存标注'}`;renderTargets();renderEntitySelects();}
function renderTargets(){$('target-list').replaceChildren();for(const t of S.annotation?.targets||[]){const row=document.createElement('div');row.className='target-row';row.innerHTML=`<div class="details"><input aria-label="目标名称" value="${esc(t.name)}"><select aria-label="目标对应实体"><option value="">未关联实体</option>${S.entities.map(e=>`<option value="${esc(e.id)}" ${e.id===t.entity_id?'selected':''}>${esc(e.name)}</option>`).join('')}</select><select data-target-area aria-label="目标所在区域"><option value="">区域未确定</option>${floorData(t.floor).regions.map(r=>`<option value="${r.id}" ${r.id===t.area_id?'selected':''}>${esc(regionOption(r))}</option>`).join('')}</select><select data-target-confidence aria-label="目标定位可信度"><option value="estimated" ${t.confidence==='estimated'?'selected':''}>目标位置：估计</option><option value="confirmed" ${t.confidence==='confirmed'?'selected':''}>目标位置：现场确认</option><option value="unknown" ${t.confidence==='unknown'?'selected':''}>目标位置：未知</option></select><input data-target-note aria-label="目标备注" placeholder="目标备注" value="${esc(t.note||'')}"><span class="small muted">${t.floor==='GF'?'G/F':'LG/F'} · ${esc(regionName(t.area_id,t.floor)||'区域未确定')} · ${t.type==='area'?'目标区域':`(${meters(t.x_px,t.y_px,t.floor).map(v=>v.toFixed(2)).join(', ')}) m`}</span></div><button class="delete" aria-label="删除目标">×</button>`;row.querySelector('input').addEventListener('input',e=>{t.name=e.target.value;touch();renderMarks();});row.querySelector('select').addEventListener('change',e=>{t.entity_id=e.target.value||null;touch();});row.querySelector('[data-target-area]').addEventListener('change',e=>{t.area_id=e.target.value||null;touch();});row.querySelector('[data-target-confidence]').addEventListener('change',e=>{t.confidence=e.target.value;touch();});row.querySelector('[data-target-note]').addEventListener('input',e=>{t.note=e.target.value;touch();});row.querySelector('.delete').onclick=()=>{S.annotation.targets=S.annotation.targets.filter(v=>v.id!==t.id);touch();renderTargets();renderMarks();};$('target-list').append(row);}if(S.annotation?.coverage?.length){const button=document.createElement('button');button.className='text-button';button.textContent=`清除 ${S.annotation.coverage.length} 个覆盖区域`;button.onclick=()=>{S.annotation.coverage=[];touch();renderMarks();renderTargets();};$('target-list').append(button);}}
function renderRelations(){$('relation-list').replaceChildren();for(const r of S.current?.relations||[]){const other=r.photo_id===S.current.id?r.other_id:r.photo_id;const photo=S.photos.find(p=>p.id===other);const row=document.createElement('div');row.className='relation-row';const kinds={overview_detail:'全景／近照',same_object:'同一物体',sequence:'连续拍摄'};row.innerHTML=`<button class="text-button">${esc(kinds[r.kind])} · ${esc(photo?.name||other)}</button><span>${esc(r.note)}</span><button class="delete" aria-label="删除关联">×</button>`;row.querySelector('button').onclick=()=>selectPhoto(other).catch(e=>toast(e.message));row.querySelector('.delete').onclick=async()=>{await api('/api/relation/delete',{id:r.id});await refreshDetail();};$('relation-list').append(row);}if(!S.current?.relations?.length)$('relation-list').textContent='尚未建立关联';}
function renderCandidates(){$('candidate-list').replaceChildren();for(const c of S.current?.candidates||[]){const card=document.createElement('article');card.className='candidate-card';card.innerHTML=`<div class="candidate-head"><strong>${esc(c.kind==='ocr'?'OCR 原文候选':c.kind==='vision'?'视觉识别候选':'导入原文')}</strong><span class="pill ${c.state==='pending'?'amber':''}">${({pending:'待审核',confirmed:'已确认',rejected:'已拒绝'})[c.state]}</span><span class="muted">${esc(c.engine)} · ${esc(c.payload.crop_label||'原文')}</span></div><textarea aria-label="核验候选内容">${esc(S.candidateDrafts?.[c.id]??c.text)}</textarea><div class="candidate-actions"><button class="primary" data-action="confirm">确认此内容</button><button data-action="reject">拒绝</button><button data-action="pending">恢复待审核</button></div><details><summary>原始结果与来源</summary><pre>${esc(JSON.stringify(c.payload,null,2))}</pre><pre>${esc(c.raw)}</pre></details>`;card.querySelector('textarea').addEventListener('input',e=>{S.candidateDrafts||={};S.candidateDrafts[c.id]=e.target.value;});for(const b of card.querySelectorAll('[data-action]'))b.onclick=async()=>{const state={confirm:'confirmed',reject:'rejected',pending:'pending'}[b.dataset.action];await api('/api/candidate/review',{id:c.id,state,edited_text:card.querySelector('textarea').value});if(S.candidateDrafts)delete S.candidateDrafts[c.id];await refreshDetail();toast('审核状态已保存');};$('candidate-list').append(card);}if(!S.current?.candidates?.length)$('candidate-list').innerHTML='<div class="empty-list">暂无候选。可运行本地 OCR／视觉识别，或导入识别原文。</div>';}
function renderFacts(){$('fact-list').replaceChildren();for(const f of S.current?.facts||[]){const card=document.createElement('article');card.className='fact-card';card.innerHTML=`<strong>${esc(f.subject)} · ${esc(f.predicate)}</strong><p>${esc(f.value)}</p><div class="meta">${f.source_kind==='human'?'人工确认记录':'识别候选经人工确认'}${f.entity_id?' · 实体 '+esc(f.entity_id):''}</div>`;$('fact-list').append(card);}if(!S.current?.facts?.length)$('fact-list').innerHTML='<div class="empty-list">尚无确认事实。备注仍以原始现场记录保存。</div>';}
async function refreshDetail(){if(!S.current)return;await flush();const pid=S.current.id,sequence=(S.refreshSequence||0)+1;S.refreshSequence=sequence;const detail=await api('/api/photo/'+pid);if(S.current?.id!==pid||S.refreshSequence!==sequence)return;S.current={...S.current,...detail};S.annotation=clone(detail.annotation);renderCandidates();renderFacts();renderRelations();}
function renderEntitySelects(){for(const id of['new-target-entity','fact-entity']){const previous=$(id).value;$(id).replaceChildren(new Option(id==='fact-entity'?'无／尚未关联':'稍后关联',''));for(const e of S.entities)$(id).append(new Option(e.name,e.id));$(id).value=previous;}}
function renderEntities(){renderEntitySelects();$('entity-list').replaceChildren();for(const e of S.entities){const photoIds=new Set();for(const p of S.photos)if(p.annotation.targets?.some(t=>t.entity_id===e.id)||p.annotation.boxes?.some(b=>b.entity_id===e.id))photoIds.add(p.id);const row=document.createElement('div');row.className='entity-item';row.innerHTML=`<strong>${esc(e.name)}</strong> <span class="small muted">${esc(e.type||'物体')}</span><div class="meta">${esc(e.id)} · 关联 ${photoIds.size} 张照片<br>${esc((e.aliases||[]).join(' / '))}</div>`;$('entity-list').append(row);}if(!S.entities.length)$('entity-list').innerHTML='<p class="hint">先为重要物体创建实体，再将照片目标关联到它。</p>';}
async function showCoverage(){const rows=await api('/api/coverage');$('coverage-list').replaceChildren();const parents=new Map();for(const row of rows){const r=floorData(row.floor).regions.find(r=>r.id===row.region_id),key=r.room_id||row.region_id;const p=parents.get(key)||{name:row.name,floor:row.floor,cameraIds:new Set(),targetIds:new Set()};for(const id of row.camera_photo_ids||[])p.cameraIds.add(id);for(const id of row.target_photo_ids||[])p.targetIds.add(id);p.camera=p.cameraIds.size;p.target=p.targetIds.size;parents.set(key,p);}for(const r of parents.values()){const item=document.createElement('div');item.className='coverage-item'+(!r.camera&&!r.target?' missing':'');item.innerHTML=`<span>${r.floor==='GF'?'G/F':'LG/F'} · ${esc(r.name)}</span><span>${r.camera+r.target?'拍摄 '+r.camera+' · 目标 '+r.target:'缺少定位照片'}</span>`;$('coverage-list').append(item);}}
function renderJobs(){$('processing-status').replaceChildren();for(const job of S.jobs.slice(0,5)){const row=document.createElement('div');row.className='job-row';row.innerHTML=`<span>${esc(({ocr:'OCR',vision:'视觉识别',index:'检索索引'})[job.mode])} · ${esc(job.message||job.state)} · 成功 ${job.success||0} · 失败 ${job.failures?.length||0}</span>${['queued','running','cancelling'].includes(job.state)?'<button>停止任务</button>':''}${job.failures?.length?'<details><summary>失败详情</summary><div class="job-errors"></div></details>':''}`;if(row.querySelector('button'))row.querySelector('button').onclick=async()=>{await api('/api/job/cancel',{id:job.id});await pollJobs();};if(job.failures?.length)row.querySelector('.job-errors').textContent=job.failures.map(f=>`${S.photos.find(p=>p.id===f.photo_id)?.name||f.photo_id}: ${f.error}`).join('\n');$('processing-status').append(row);}}
let pollTimer=null;async function pollJobs(){const previous=S.jobs;S.jobs=await api('/api/jobs');renderJobs();const completed=S.jobs.some(j=>j.state==='completed'&&previous.some(p=>p.id===j.id&&p.state!=='completed'));if(completed)await refreshDetail();clearTimeout(pollTimer);if(S.jobs.some(j=>['queued','running','cancelling'].includes(j.state)))pollTimer=setTimeout(()=>pollJobs().catch(e=>toast(e.message)),1500);}
async function switchView(view){await flush();S.view=view;for(const v of['annotate','evidence','calibration'])$(v+'-view').hidden=v!==view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='evidence'){await refreshDetail();renderEntities();showCoverage();pollJobs();}if(view==='annotate'){setMapView();renderPhoto();}}
function renderCalibration(){const c=S.maps.calibration;$('calibration-tables').replaceChildren();for(const f of S.maps.floors){const block=document.createElement('section');let content=`<h2 class="calibration-table-title">${f.label} · 尺寸控制点</h2><p class="hint">独立拟合 X／Y 轴；读图约 1 px ≈ 5.3 cm。下列残差只描述轴网拟合，不表示现场定位精度。</p><div class="table-wrap"><table><thead><tr><th>轴</th><th>图中位置（px）</th><th>图纸坐标（m）</th><th>拟合残差（m）</th></tr></thead><tbody>`;for(const axis of['x','y'])for(const p of c.floors[f.id][axis].controls)content+=`<tr><td>${esc(p.axis)} · ${axis.toUpperCase()}</td><td>${p.pixel}</td><td>${p.meters.toFixed(2)}</td><td>${p.residual_m.toFixed(4)}</td></tr>`;content+='</tbody></table></div>';block.innerHTML=content;$('calibration-tables').append(block);}const body=$('room-table').querySelector('tbody');body.replaceChildren();for(const f of S.maps.floors)for(const r of f.regions){const row=document.createElement('tr');row.innerHTML=`<td>${f.label} · ${r.id}</td><td>${esc(r.label)}${r.is_historical_subregion?'<br><span class="muted">真实父空间的历史子区</span>':''}</td><td>${esc(r.official_plan_name||'无独立房名')}</td><td>${r.site_name?'现场确认 '+r.site_name_confirmed_at.slice(0,10):r.name_source_date||'2020 尺寸图'}${r.name_source?` · <a href="${esc(r.name_source)}" target="_blank" rel="noopener noreferrer">官方来源</a>`:''}</td><td>${r.type==='circulation'?'通行分段，非独立房间':'待现场核对'}<br><button class="text-button" data-confirm-room>确认房名</button></td>`;row.querySelector('[data-confirm-room]').onclick=()=>{S.editRoom={floor:f.id,region_id:r.id};$('room-name-reference').textContent=`${f.label} · ${r.id} · 官方原名：${r.official_name||r.official_plan_name||'无独立房名'}`;$('room-name-value').value=r.label;$('room-name-note').value=r.site_name_note||'';$('room-name-dialog').showModal();};body.append(row);}renderDistanceOptions();}
function renderDistanceOptions(){const floor=$('distance-floor').value;for(const id of['distance-a','distance-b']){$(id).replaceChildren();for(const r of floorData(floor).regions)$(id).append(new Option(regionOption(r),r.id));}if($('distance-b').options.length>1)$('distance-b').selectedIndex=1;}
function segmentDistance(p,a,b){const vx=b[0]-a[0],vy=b[1]-a[1],length=vx*vx+vy*vy,t=length?Math.max(0,Math.min(1,((p[0]-a[0])*vx+(p[1]-a[1])*vy)/length)):0;return Math.hypot(p[0]-(a[0]+t*vx),p[1]-(a[1]+t*vy));}
function cross(a,b,c){return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);}
function intersect(a,b,c,d){const ca=cross(a,b,c),cb=cross(a,b,d),cc=cross(c,d,a),cd=cross(c,d,b);return ca*cb<=0&&cc*cd<=0&&Math.max(Math.min(a[0],b[0]),Math.min(c[0],d[0]))<=Math.min(Math.max(a[0],b[0]),Math.max(c[0],d[0]))+1e-9&&Math.max(Math.min(a[1],b[1]),Math.min(c[1],d[1]))<=Math.min(Math.max(a[1],b[1]),Math.max(c[1],d[1]))+1e-9;}
function boundaryDistance(a,b){if(inPolygon(a[0],b)||inPolygon(b[0],a))return 0;let distance=Infinity;for(let i=0;i<a.length;i++)for(let j=0;j<b.length;j++){const aa=a[i],ab=a[(i+1)%a.length],ba=b[j],bb=b[(j+1)%b.length];if(intersect(aa,ab,ba,bb))return 0;distance=Math.min(distance,segmentDistance(aa,ba,bb),segmentDistance(ab,ba,bb),segmentDistance(ba,aa,ab),segmentDistance(bb,aa,ab));}return distance;}
function calculateDistance(){const f=floorData($('distance-floor').value),a=f.regions.find(r=>r.id===$('distance-a').value),b=f.regions.find(r=>r.id===$('distance-b').value);const ac=a.centroid_m||meters(...a.at,f.id),bc=b.centroid_m||meters(...b.at,f.id);const ap=a.points.map(p=>meters(...p,f.id)),bp=b.points.map(p=>meters(...p,f.id));$('room-distance-result').innerHTML=`<strong>${esc(a.label)} ↔ ${esc(b.label)}</strong><br>几何中心直线距离：<strong>${Math.hypot(ac[0]-bc[0],ac[1]-bc[1]).toFixed(2)} m</strong> · 区域边界最短间距：<strong>${boundaryDistance(ap,bp).toFixed(2)} m</strong><br><span class="small muted">基于人工描绘的图纸分区；单位待核验${a.room_id===b.room_id?'。这两个子区属于同一真实父空间。':''}</span>`;}

function requirePhoto(){if(S.loading)throw Error('照片正在加载，请稍候');if(!S.current)throw Error('先选择一张照片');}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view).catch(e=>toast(e.message))));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
for(const id of['folder-filter','status-filter','photo-floor-filter'])on(id,'change',filterPhotos);on('photo-search','input',filterPhotos);
on('previous-photo','click',()=>movePhoto(-1));on('next-photo','click',()=>movePhoto(1));
on('select-visible','change',e=>{for(const p of S.filtered)if(e.target.checked)S.selected.add(p.id);else S.selected.delete(p.id);renderLibrary();});
on('map-floor','change',async e=>{requirePhoto();await flush();const next=e.target.value;if(S.annotation.floor&&S.annotation.floor!==next){S.annotation.camera=null;S.annotation.heading_deg=null;S.annotation.targets=[];S.annotation.coverage=[];S.annotation.camera_area=null;S.annotation.position_confidence='unknown';S.annotation.heading_confidence='unknown';S.annotation.status='review';toast('已切换楼层，请重新设置该照片的位置与方向。旧记录可从历史恢复。');}S.floor=next;S.annotation.floor=next;S.polygon=[];S.measure=[];renderMap();fillForm();touch();});
on('map-background','change',()=>{const mode=$('map-background').value;$('map-image').style.display=mode==='regions'?'none':'';$('map-regions').style.display=mode==='original'?'none':'';renderMapLabels();});
on('map-labels','change',renderMapLabels);on('map-grid-toggle','change',renderGrid);on('map-zoom','input',e=>{S.mapZoom=Number(e.target.value);setMapView();});on('map-fit','click',()=>{const f=floorData();S.mapZoom=1;S.mapCenter=[f.width/2,f.height/2];$('map-zoom').value=1;setMapView();});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{S.mapMode=b.dataset.mode;S.polygon=[];document.querySelectorAll('[data-mode]').forEach(v=>v.classList.toggle('active',v===b));$('finish-coverage').hidden=!['coverage','target-area'].includes(S.mapMode);$('finish-coverage').textContent=S.mapMode==='target-area'?'完成目标区域':'完成覆盖区域';$('map-detail').textContent={camera:'点击拍摄者的位置；可拖动蓝色点调整。',heading:'点击相机朝向，或拖动蓝色箭头末端。',target:'填写目标名称，然后点击目标所在位置。','target-area':'填写目标名称，逐点绘制目标范围，然后完成目标区域。',coverage:'逐点绘制覆盖范围，点击“完成覆盖区域”保存。',measure:'依次点击两个点，测量平面直线距离。',pan:'放大后拖动地图平移。'}[S.mapMode];renderMarks();}));
on('finish-coverage','click',()=>{requirePhoto();if(S.polygon.length<3)throw Error('区域至少需要三个点');S.annotation.floor||=S.floor;if(S.mapMode==='target-area'){const center=S.polygon.reduce((a,p)=>[a[0]+p[0]/S.polygon.length,a[1]+p[1]/S.polygon.length],[0,0]);S.annotation.targets.push({id:'target_'+crypto.randomUUID().slice(0,12),type:'area',floor:S.floor,name:$('new-target-name').value.trim()||'未命名目标区域',entity_id:$('new-target-entity').value||null,points_px:clone(S.polygon),area_id:regionsAt(...center)[0]?.id||null,confidence:'estimated',note:''});}else S.annotation.coverage.push({id:'coverage_'+crypto.randomUUID().slice(0,12),points_px:clone(S.polygon),confidence:'estimated'});S.polygon=[];touch();renderMarks();renderTargets();});
let mapDrag=null;$('map-svg').addEventListener('pointerdown',event=>{const point=svgPoint($('map-svg'),event);mapDrag={x:event.clientX,y:event.clientY,point:[point.x,point.y],center:[...S.mapCenter],target:event.target,moved:false};$('map-svg').setPointerCapture(event.pointerId);});
$('map-svg').addEventListener('pointermove',event=>{const point=svgPoint($('map-svg'),event),frame=floorData();point.x=Math.max(0,Math.min(frame.width,point.x));point.y=Math.max(0,Math.min(frame.height,point.y));const m=meters(point.x,point.y);$('map-coordinates').textContent=`X ${m[0].toFixed(2)} m · Y ${m[1].toFixed(2)} m`;if(!mapDrag)return;const dx=event.clientX-mapDrag.x,dy=event.clientY-mapDrag.y;if(Math.abs(dx)+Math.abs(dy)>4)mapDrag.moved=true;if(!mapDrag.moved)return;const kind=mapDrag.target.dataset.markKind;if(kind&&S.current){if(kind==='camera'){S.annotation.camera.x_px=point.x;S.annotation.camera.y_px=point.y;S.annotation.camera_area=regionsAt(point.x,point.y)[0]?.id||null;touch();renderPositionValues();renderMarks();}else if(kind==='heading')setHeading(point.x,point.y);else if(kind==='target'){const t=S.annotation.targets.find(t=>t.id===mapDrag.target.dataset.markId);if(t){t.x_px=point.x;t.y_px=point.y;t.area_id=regionsAt(point.x,point.y)[0]?.id||null;touch();renderTargets();renderMarks();}}}else if(S.mapMode==='pan'||S.mapZoom>1){const scale=screenScale();S.mapCenter=[mapDrag.center[0]-dx/scale,mapDrag.center[1]-dy/scale];setMapView();}});
$('map-svg').addEventListener('pointerup',event=>{if(!mapDrag)return;const drag=mapDrag;mapDrag=null;if($('map-svg').hasPointerCapture(event.pointerId))$('map-svg').releasePointerCapture(event.pointerId);if(drag.moved)return;const p=svgPoint($('map-svg'),event),f=floorData();if(p.x<0||p.y<0||p.x>f.width||p.y>f.height)return;if(!S.current&&S.mapMode!=='measure'){toast('先选择照片。');return;}if(S.mapMode==='camera')placeCamera(p.x,p.y);else if(S.mapMode==='heading')setHeading(p.x,p.y);else if(S.mapMode==='target')placeTarget(p.x,p.y);else if(['coverage','target-area'].includes(S.mapMode)){S.polygon.push([p.x,p.y]);renderMarks();}else if(S.mapMode==='measure'){if(S.measure.length===2)S.measure=[];S.measure.push([p.x,p.y]);renderMarks();}});
$('map-svg').addEventListener('pointercancel',()=>{mapDrag=null;});
on('photo-zoom','input',e=>{requirePhoto();S.photoZoom=Number(e.target.value);renderPhoto();});on('photo-fit','click',()=>{requirePhoto();S.photoZoom=1;S.photoCenter=[S.current.width/2,S.current.height/2];renderPhoto();});on('box-mode','click',()=>{requirePhoto();S.boxMode=!S.boxMode;renderPhoto();});on('clear-boxes','click',()=>{requirePhoto();S.annotation.boxes=[];touch();renderPhoto();});
let photoDrag=null;$('photo-svg').addEventListener('pointerdown',event=>{if(!S.current)return;const p=svgPoint($('photo-svg'),event);photoDrag={x:event.clientX,y:event.clientY,point:[p.x,p.y],center:[...S.photoCenter]};$('photo-svg').setPointerCapture(event.pointerId);});
$('photo-svg').addEventListener('pointermove',event=>{if(!photoDrag)return;const p=svgPoint($('photo-svg'),event);if(S.boxMode){let rect=$('draft-box');if(!rect){rect=svgEl('rect',{id:'draft-box',fill:'#f5b64525',stroke:'#e5a22a','stroke-width':2,'vector-effect':'non-scaling-stroke'});$('photo-boxes').append(rect);}for(const[k,v]of Object.entries({x:Math.min(p.x,photoDrag.point[0]),y:Math.min(p.y,photoDrag.point[1]),width:Math.abs(p.x-photoDrag.point[0]),height:Math.abs(p.y-photoDrag.point[1])}))rect.setAttribute(k,v);}else if(S.photoZoom>1){const c=$('photo-svg').getScreenCTM(),scale=Math.hypot(c.a,c.b);S.photoCenter=[photoDrag.center[0]-(event.clientX-photoDrag.x)/scale,photoDrag.center[1]-(event.clientY-photoDrag.y)/scale];renderPhoto();}});
$('photo-svg').addEventListener('pointerup',event=>{if(!photoDrag)return;const start=photoDrag.point,p=svgPoint($('photo-svg'),event);photoDrag=null;if($('photo-svg').hasPointerCapture(event.pointerId))$('photo-svg').releasePointerCapture(event.pointerId);if(S.boxMode){const x=Math.max(0,Math.min(start[0],p.x)),y=Math.max(0,Math.min(start[1],p.y)),right=Math.min(S.current.width,Math.max(start[0],p.x)),bottom=Math.min(S.current.height,Math.max(start[1],p.y));if(right-x>20&&bottom-y>20){S.annotation.boxes.push({id:'box_'+crypto.randomUUID().slice(0,12),name:'细节 '+(S.annotation.boxes.length+1),x:x/S.current.width,y:y/S.current.height,width:(right-x)/S.current.width,height:(bottom-y)/S.current.height,entity_id:$('new-target-entity').value||null});touch();}renderPhoto();}});
$('photo-svg').addEventListener('pointercancel',()=>{photoDrag=null;renderPhoto();});
const bindings={'camera-area':['camera_area',v=>v||null],'position-confidence':['position_confidence',v=>v],'heading':['heading_deg',v=>v===''?null:Number(v)],'heading-confidence':['heading_confidence',v=>v],'fov':['fov_deg',v=>v===''?null:Number(v)],'pitch':['pitch_deg',v=>v===''?null:Number(v)],'pitch-mode':['pitch_mode',v=>v],'captured-at':['captured_at',v=>v||null],'photo-type':['photo_type',v=>v],'group-id':['group_id',v=>v],'tags':['tags',v=>v.split(/[,，]/).map(t=>t.trim()).filter(Boolean)],'annotation-status':['status',v=>v]};
for(const[id,[key,transform]]of Object.entries(bindings))on(id,['INPUT','TEXTAREA'].includes($(id).tagName)?'input':'change',e=>{requirePhoto();S.annotation[key]=transform(e.target.value);if(key==='heading_deg'&&S.annotation[key]===null&&S.annotation.status==='marked')S.annotation.status='review';if(key==='pitch_deg'&&S.annotation[key]!==null){S.annotation.pitch_mode=S.annotation[key]>0?'up':S.annotation[key]<0?'down':'horizontal';$('pitch-mode').value=S.annotation.pitch_mode;}if(key==='heading_deg'&&S.annotation[key]!==null&&S.annotation.camera){S.annotation.status='marked';if(S.annotation.heading_confidence==='unknown')S.annotation.heading_confidence='estimated';}touch();renderMarks();});
for(const[k,id]of Object.entries({shooting:'note-shooting',content:'note-content',correspondence:'note-correspondence',uncertainty:'note-uncertainty'}))on(id,'input',e=>{requirePhoto();S.annotation.notes[k]=e.target.value;touch();});
on('clear-position','click',()=>{requirePhoto();S.annotation.camera=null;S.annotation.heading_deg=null;S.annotation.camera_area=null;S.annotation.position_confidence='unknown';S.annotation.heading_confidence='unknown';S.annotation.status='unknown';touch();fillForm();renderMarks();});
on('save','click',async()=>{requirePhoto();await flush();toast('标注已保存到磁盘');if($('auto-next').checked)await movePhoto(1);});on('undo','click',async()=>{requirePhoto();await flush();const a=await api('/api/undo',{photo_id:S.current.id});S.annotation=a;S.photos.find(p=>p.id===S.current.id).annotation=clone(a);fillForm();renderMarks();renderPhoto();updateCard(S.current.id);toast('已恢复上一版本');});
on('import-folder','click',()=>$('folder-input').click());on('folder-input','change',async event=>{const files=[...event.target.files].filter(f=>/^image\//.test(f.type)||/\.(jpe?g|png|webp|gif|tiff?)$/i.test(f.name));let n=0;for(const file of files){setSaveState(`导入 ${++n} / ${files.length}`,'saving');const r=await fetch('/api/upload?path='+encodeURIComponent(file.webkitRelativePath||file.name),{method:'POST',body:file});if(!r.ok){const e=await r.json();throw Error(e.error);}}S.photos=await api('/api/photos');buildFolders();filterPhotos();setSaveState('导入完成');toast(`已导入 ${files.length} 张来源图片，相同内容自动合并`);event.target.value='';});
on('restore-open','click',()=>$('restore-input').click());on('restore-input','change',async e=>{if(!e.target.files[0])return;await flush();const value=JSON.parse(await e.target.files[0].text());const result=await api('/api/restore',value);S.photos=await api('/api/photos');buildFolders();filterPhotos();await refreshDetail();toast(`已恢复 ${result.restored} 张照片的记录；旧数据库已自动备份`);e.target.value='';});
on('batch-open','click',async()=>{await flush();if(!S.selected.size)throw Error('先勾选需要批量设置的照片');$('batch-description').textContent=`将修改 ${S.selected.size} 张照片，留空的字段不变。`;$('batch-dialog').showModal();});on('batch-floor','change',()=>{const f=$('batch-floor').value;$('batch-area').replaceChildren(new Option('不修改',''));if(f)for(const r of floorData(f).regions)$('batch-area').append(new Option(regionOption(r),r.id));});on('batch-form','submit',async e=>{e.preventDefault();const patch={};if($('batch-date').value)patch.captured_at=$('batch-date').value;if($('batch-type').value)patch.photo_type=$('batch-type').value;if($('batch-group').value)patch.group_id=$('batch-group').value;if($('batch-floor').value)patch.floor=$('batch-floor').value;if($('batch-area').value)patch.camera_area=$('batch-area').value;if($('batch-status').value)patch.status=$('batch-status').value;if($('batch-tags').value)patch.tags=$('batch-tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean);const result=await api('/api/batch',{photo_ids:[...S.selected],patch});$('batch-dialog').close();S.photos=await api('/api/photos');buildFolders();filterPhotos();await refreshDetail();toast(`已批量更新 ${result.updated} 张照片`);});
on('copy-open','click',async()=>{requirePhoto();await flush();const i=S.filtered.findIndex(p=>p.id===S.current.id);if(i<=0)throw Error('当前列表没有上一张照片');$('copy-source').textContent='来源：'+S.filtered[i-1].name;$('copy-dialog').showModal();});on('copy-form','submit',async e=>{e.preventDefault();const i=S.filtered.findIndex(p=>p.id===S.current.id);if(i<=0)return;const a=S.filtered[i-1].annotation;const form=e.target;if(form.elements.camera.checked)for(const k of['camera','floor','camera_area','position_confidence'])S.annotation[k]=clone(a[k]);if(form.elements.heading.checked)for(const k of['heading_deg','heading_confidence','pitch_mode','pitch_deg','fov_deg'])S.annotation[k]=clone(a[k]);if(form.elements.notes.checked)S.annotation.notes=clone(a.notes);if(form.elements.metadata.checked)for(const k of['captured_at','photo_type','group_id','tags'])S.annotation[k]=clone(a[k]);S.annotation.status=S.annotation.camera&&S.annotation.heading_deg!==null?'marked':'review';S.floor=S.annotation.floor||S.floor;touch();await flush();$('copy-dialog').close();renderMap();fillForm();toast('已复制并保存');});
on('link-open','click',async()=>{requirePhoto();await flush();$('link-photo').replaceChildren();for(const p of S.photos)if(p.id!==S.current.id)$('link-photo').append(new Option(p.folder_hint+' / '+p.name,p.id));$('link-dialog').showModal();});on('link-form','submit',async e=>{e.preventDefault();await api('/api/relation',{photo_id:S.current.id,other_id:$('link-photo').value,kind:$('link-kind').value,note:$('link-note').value});$('link-dialog').close();await refreshDetail();});
on('settings-open','click',async()=>{const c=await api('/api/config');$('vision-url').value=c.vision_url;$('vision-model').value=c.vision_model;$('auth-mode').value=c.auth_mode;$('ocr-language').value=c.ocr_language;$('vision-key').value='';$('config-status').textContent=`视觉密钥：${c.key_configured?'已在进程中配置':'未配置'} · 本地 OCR：${c.local_ocr_available?'可用':'未检测到引擎'}`;$('settings-dialog').showModal();});on('settings-form','submit',async e=>{e.preventDefault();S.config=await api('/api/config',{vision_url:$('vision-url').value,vision_model:$('vision-model').value,auth_mode:$('auth-mode').value,api_key:$('vision-key').value,ocr_language:$('ocr-language').value});$('vision-key').value='';$('settings-dialog').close();toast('处理设置已保存；密钥仅在本次服务进程中保留');});
on('process-start','click',async()=>{await flush();const scope=$('process-scope').value,ids=scope==='all'?S.photos.map(p=>p.id):scope==='filtered'?S.filtered.map(p=>p.id):scope==='selected'?[...S.selected]:S.current?[S.current.id]:[];if(!ids.length)throw Error('没有选择需要处理的照片');await api('/api/process',{photo_ids:ids,mode:$('process-mode').value,tiles:$('process-tiles').checked});await pollJobs();toast('处理任务已开始，结果作为候选保存');});
on('import-ocr-open','click',()=>{requirePhoto();$('ocr-dialog').showModal();});on('ocr-form','submit',async e=>{e.preventDefault();await api('/api/candidate/import',{photo_id:S.current.id,text:$('ocr-text').value,engine:$('ocr-engine').value});$('ocr-dialog').close();await refreshDetail();});
on('fact-open','click',()=>{requirePhoto();renderEntitySelects();$('fact-dialog').showModal();});on('fact-form','submit',async e=>{e.preventDefault();await api('/api/fact',{photo_id:S.current.id,subject:$('fact-subject').value,predicate:$('fact-predicate').value,value:$('fact-value').value,entity_id:$('fact-entity').value||null,source_kind:'human'});$('fact-dialog').close();await refreshDetail();});
on('entity-open','click',()=>$('entity-dialog').showModal());on('entity-form','submit',async e=>{e.preventDefault();const entity=await api('/api/entity',{name:$('entity-name').value,type:$('entity-type').value,aliases:$('entity-aliases').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),description:$('entity-description').value});S.entities.unshift(entity);$('entity-dialog').close();renderEntities();renderTargets();toast('实体已创建，可关联照片中的目标');});
on('room-name-form','submit',async e=>{e.preventDefault();await flush();S.maps=await api('/api/room-name',{...S.editRoom,name:$('room-name-value').value,note:$('room-name-note').value});$('room-name-dialog').close();renderMap();fillForm();renderCalibration();toast('现场房名已保存，官方原名与坐标保留');});
on('evidence-search','click',async()=>{await flush();const results=await api('/api/search?q='+encodeURIComponent($('evidence-query').value));$('search-results').replaceChildren();for(const r of results){const p=S.photos.find(p=>p.id===r.photo_id),row=document.createElement('div');row.className='search-result';row.innerHTML=`<button>${esc(p?.folder_hint)} / ${esc(p?.name)}</button><p>${esc(r.snippet)}</p>`;row.querySelector('button').onclick=async()=>{await selectPhoto(r.photo_id);await switchView('annotate');};$('search-results').append(row);}if(!results.length)$('search-results').innerHTML='<p class="hint">未找到匹配证据。可先重建索引或补充记录。</p>';});on('evidence-query','keydown',e=>{if(e.key==='Enter')$('evidence-search').click();});on('coverage-refresh','click',showCoverage);on('distance-floor','change',renderDistanceOptions);on('distance-calculate','click',calculateDistance);
document.addEventListener('keydown',event=>{if(event.ctrlKey&&event.key.toLowerCase()==='s'){event.preventDefault();flush().then(()=>toast('已保存')).catch(e=>toast(e.message));return;}if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;if(event.key==='ArrowLeft')movePhoto(-1).catch(e=>toast(e.message));if(event.key==='ArrowRight')movePhoto(1).catch(e=>toast(e.message));});
window.addEventListener('beforeunload',event=>{if(S.dirty||S.saving){event.preventDefault();event.returnValue='标注尚未保存';}});
new ResizeObserver(()=>{if(S.maps){renderMapLabels();renderGrid();renderMarks();}}).observe($('map-svg'));
async function boot(){const data=await api('/api/bootstrap');S.maps=data.maps;S.photos=data.photos;S.entities=data.entities;S.config=data.config;S.jobs=data.jobs;buildFolders();filterPhotos();renderMap();renderCalibration();renderEntities();renderJobs();const last=localStorage.getItem('innowing-last-photo');if(S.photos.length)await selectPhoto(S.photos.some(p=>p.id===last)?last:S.photos[0].id);else setSaveState('可以导入照片');if(S.jobs.some(j=>['queued','running'].includes(j.state)))pollJobs();}
boot().catch(error=>{toast(error.message);setSaveState('载入失败','error');});
